.suspend-btn {
    background: #f43f5e;
}

.reactivate-btn {
    background: #10b981;
}

.cancel-btn:hover { background: #475569; }
.suspend-btn:hover { background: #e11d48; transform: translateY(-2px); }
.reactivate-btn:hover { background: #059669; transform: translateY(-2px); }

/* Animations */
@keyframes scaleUp {
    from { transform: scale(0.9); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* "(You)" — small inline pill beside the name; never allowed to line-break
   on its own (the old italic text wrapped as "(You" + ")"). */
.self-tag {
    display: inline-flex;
    align-items: center;
    white-space: nowrap;
    flex-shrink: 0;
    margin-left: 6px;
    padding: 1px 8px;
    border-radius: 999px;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #93c5fd;
    background: rgba(59, 130, 246, 0.12);
    border: 1px solid rgba(59, 130, 246, 0.3);
}

/* =========================================
   LAPTOP RESPONSIVENESS (1025px - 1366px)
   Keeps the full desktop table; the responsive card layout below owns <=1024px.
   ========================================= */
@media (max-width: 1366px) and (min-width: 1025px) {
    .users-table th,
    .users-table td {
        padding: 14px 12px;
        font-size: 0.85rem; 
    }

    /* 🎯 THE MAGIC FIX: Forces badges, dates, and buttons to stay on one straight line */
    .user-name-text,
    .role-badge,
    .presence-tag,
    .time-cell,
    .actions-cell {
        white-space: nowrap;

