/* =========================================
   STAFF MANAGEMENT BADGES (page-specific — the generic .status-badge is
   styled by several pages and collides in the production CSS bundle)
   ========================================= */
.staff-face-badge,
.staff-presence-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.staff-face-badge.is-enrolled,
.staff-presence-badge {
    background: rgba(16, 185, 129, 0.1);
    color: #10b981;
    border: 1px solid rgba(16, 185, 129, 0.2);
}

.staff-face-badge.not-enrolled {
    background: #334155;
    color: #cbd5e1;
    border: 1px solid rgba(148, 163, 184, 0.25);
}

/* Desktop: give the Face ID and Status columns room so badges never clip. */
.staff-table th:nth-child(3),
.staff-table td:nth-child(3) { min-width: 140px; }
.staff-table th:nth-child(4),
.staff-table td:nth-child(4) { min-width: 110px; }

@media (max-width: 768px) {
    /* The card layout stacks cells full-width; min-widths are unnecessary there. */
    .staff-table th:nth-child(3),
    .staff-table td:nth-child(3),
    .staff-table th:nth-child(4),
    .staff-table td:nth-child(4) { min-width: 0; }
}

/* Phones: keep the existing card behavior; drop min-widths so nothing overflows. */
@media (max-width: 768px) {
    .security-review-table { min-width: 0; }

