file.content:
/* --- Dark Mode Table Styling --- */
/* No forced min-width: the fixed layout + percentage columns below make the
   table fit the desktop viewport without a horizontal scrollbar. */
.users-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    text-align: left;
    color: #f8fafc;
}

/* Personnel */
.users-table th:nth-child(1),
.users-table td:nth-child(1) {
    width: 20%;
}

/* Role */
.users-table th:nth-child(2),
.users-table td:nth-child(2) {
    width: 11%;
}

/* Email */
.users-table th:nth-child(3),
.users-table td:nth-child(3) {
    width: 21%;
}

/* Status */
.users-table th:nth-child(4),
.users-table td:nth-child(4) {
    width: 9%;
}

/* Face ID */
.users-table th:nth-child(5),
.users-table td:nth-child(5) {
    width: 11%;
}

/* Joined */
.users-table th:nth-child(6),
.users-table td:nth-child(6) {
    width: 9%;
}

/* Actions */
.users-table th:nth-child(7),
.users-table td:nth-child(7) {
    width: 19%;
}

.users-table th {
    background-color: rgba(15, 23, 42, 0.4);
    padding: 16px 14px;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: #94a3b8;
    font-weight: 700;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #334155;
}

/* --- UPDATED: Aligns "ACTIONS" header to the center --- */
.users-table th:last-child {
    text-align: center;
}

.users-table td {
    padding: 14px;
    border-bottom: 1px solid #334155;
    font-size: 0.92rem;
    vertical-align: middle;
}

.users-table tbody tr:hover {
    background-color: rgba(51, 65, 85, 0.3); 
}

/* --- User Info Section --- */
.user-name-cell {
    font-weight: 700;
    min-width: 0;
    overflow-wrap: anywhere;
}

.user-identity {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.user-avatar-small {
    width: 30px;
    height: 30px;
    background: linear-gradient(135deg, #6366f1, #3b82f6);
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-weight: bold;
    font-size: 0.8rem;
    color: white;
    flex-shrink: 0;
}

.user-name-text {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    row-gap: 2px;
    min-width: 0;
}

/* Long names may wrap, but the (You) pill beside them never breaks apart. */
.user-name-value {
    min-width: 0;
    white-space: normal;
    overflow-wrap: anywhere;
}

.email-cell { min-width: 0; white-space: normal; overflow-wrap: anywhere; }

/* --- Presence Status Tags --- */
.presence-tag {
    display: inline-flex;
    align-items: center;

