const out = {};
const line = document.querySelector('.user-name-line');
const cs = getComputedStyle(line);
out.line = { display: cs.display, flexWrap: cs.flexWrap, alignItems: cs.alignItems, gap: cs.gap, whiteSpace: cs.whiteSpace };
const badge = document.getElementById('you1');
const bcs = getComputedStyle(badge);
out.badge = { display: bcs.display, marginTop: bcs.marginTop, margin: bcs.margin };
// same-line checks: badge vertical center within name's line box
for (const [id, nameSel] of [['you1', 0], ['you2', 1]]) {
  const b = document.getElementById(id);
  const name = document.querySelectorAll('.user-name-value')[nameSel];
  const nr = name.getBoundingClientRect(), br = b.getBoundingClientRect();
  out[id] = {
    sameLine: br.top < nr.bottom && br.bottom > nr.top,
    badgeRight: Math.round(br.left) >= Math.round(nr.left),
    nameEllipsed: name.scrollWidth > name.clientWidth
  };
}
const td = document.querySelector('.user-name-cell');
out.personnelColWidth = Math.round(td.getBoundingClientRect().width);
out.viewport = window.innerWidth;
return JSON.stringify(out);
})()

