      ? <><SafeMuiIcon icon={CheckCircleIcon} fontSize="small" aria-hidden="true" /> Enrolled</>
      : <><SafeMuiIcon icon={CancelIcon} fontSize="small" aria-hidden="true" /> Not Enrolled</>}
  </span>
);

