const cy = el => { const r = el.getBoundingClientRect(); return r.top + r.height / 2; };
const badge = document.getElementById('badge1');
const desc = document.getElementById('desc1');
const roletd = document.getElementById('roletd');
const ws = getComputedStyle(document.getElementById('rolewrap'));
const centered = (el, cell, tol=2) => Math.abs(cx(el) - cx(cell)) <= tol;
const tds = [...document.querySelectorAll('tbody td')];
const rowMiddle = tds.every(td => getComputedStyle(td).verticalAlign === 'middle');
const pads = new Set(tds.map(td => getComputedStyle(td).padding));
return JSON.stringify({
  roleWrap: { direction: ws.flexDirection, align: ws.alignItems, gap: ws.gap, textAlign: ws.textAlign },
  badgeAboveDesc: badge.getBoundingClientRect().bottom <= desc.getBoundingClientRect().top + 1,
  badgeCenteredOverDesc: Math.abs(cx(badge) - cx(desc)) <= 2,
  roleCenteredInCell: centered(badge, roletd),
  descTextAlign: getComputedStyle(desc).textAlign,
  statusCentered: centered(document.getElementById('status1'), document.getElementById('statustd')),
  faceCentered: centered(document.getElementById('face1'), document.getElementById('facetd')),
  joinedTextAlign: getComputedStyle(document.getElementById('joined1')).textAlign,
  actionsCentered: centered(document.querySelector('.action-btn'), document.getElementById('actionstd')),
  personnelLeft: getComputedStyle(document.querySelector('.user-name-cell')).textAlign,
  emailLeft: getComputedStyle(document.getElementById('email1')).textAlign,
  allCellsMiddle: rowMiddle,
  uniformPadding: [...pads],
  youStillBesideName: (() => { const n = document.getElementById('name1').getBoundingClientRect(), y = document.getElementById('you1').getBoundingClientRect(); return y.top < n.bottom && y.bottom > n.top && y.left >= n.right - 2; })(),
  emailOneLine: (() => { const e = document.getElementById('email1'); const r = document.createRange(); r.selectNodeContents(e); return r.getClientRects().length === 1; })()
});
})()

