(() => {
const cx = el => { const r = el.getBoundingClientRect(); return r.left + r.width / 2; };
const centered = (a, b, tol=2.5) => Math.abs(cx(document.getElementById(a)) - cx(document.getElementById(b))) <= tol;
const run = () => ({
  fmBadgeOverDesc: centered('badge1', 'desc1'),
  fmCenteredInCell: centered('badge1', 'roletd'),
  tenantBadgeOverDesc: centered('badge2', 'desc2'),
  tenantCenteredInCell: centered('badge2', 'roletd2'),
  suspendedCentered: centered('status1', 'statustd'),
  activeCentered: centered('status2', 'statustd2'),
  notEnrolledCentered: centered('face1', 'facetd'),
  enrolledCentered: centered('face2', 'facetd2'),
  actionsCentered: centered('btn1', 'actionstd'),
  nameFull: document.getElementById('name1').scrollWidth <= document.getElementById('name1').clientWidth + 1,
  youBeside: (() => { const n = document.getElementById('name1').getBoundingClientRect(), y = document.getElementById('you1').getBoundingClientRect(); return y.top < n.bottom && y.bottom > n.top && y.left >= n.right - 2; })(),
  emailFullOneLine: (() => { const e = document.getElementById('email1'); const r = document.createRange(); r.selectNodeContents(e); return r.getClientRects().length === 1 && e.scrollWidth <= e.clientWidth + 1; })(),
  suspendedFits: document.getElementById('status1').getBoundingClientRect().width <= document.getElementById('statustd').clientWidth - 18,
  wrapScrolls: document.getElementById('wrap').scrollWidth > document.getElementById('wrap').clientWidth + 1
});
const res = { viewport: window.innerWidth };
res.at978 = run();
document.getElementById('sizer').style.width = '1400px';
res.at1400 = run();
document.getElementById('sizer').style.width = '978px';
return JSON.stringify(res, null, 1);
})()

