1	import React, { useEffect, useRef, useState } from 'react';
2	import { Link, useSearchParams } from 'react-router-dom';
3	import axios from 'axios';
4	import Sidebar from '../components/Sidebar';
5	import RecognitionDecisionCard, { DECISION_STATES } from '../components/RecognitionDecisionCard';
6	import ImageBasedEvaluation from '../components/ImageBasedEvaluation';
7	import useEvaluationParticipants from '../hooks/useEvaluationParticipants';
8	import '../css/Dashboard.css';
9	import '../css/FacialEvaluation.css';
10	import { API_BASE_URL } from '../constants/api';
11	import { CAMERA_SOURCES, CAMERA_STATUS_MESSAGES, isPiCameraReachable, fetchPiSnapshotBitmap } from '../constants/piCamera';
12	import {
13	  SCENARIOS,
14	  ENROLLED_LABELS,
15	  IDENTITY_LABELS,
16	  NO_FACE,
17	  UNKNOWN_LABEL,
18	  CONDITIONS,
19	  SOURCES,
20	  ORIGINS,
21	  EVAL_STORAGE_KEY,
22	  EVAL_LABEL_MAP_KEY,
23	  SIM_USERS_KEY,
24	  DETECTION_OUTCOMES,
25	  loadRecords,
26	  saveRecords,
27	  createRecord,
28	  filterRecords,
29	  computeConfusionMatrix,
30	  toCsv,
31	  loadLabelMap,
32	  saveLabelMap,
33	  assignLabel,
34	  removeMappedUser,
35	  labelForUserId,
36	  loadSimUsers,
37	  saveSimUsers,
38	  buildEvaluationDraftFromRecognition,
39	  saveEvaluationRecordFromDraft,
40	  notifyEvaluationRecordsUpdated,
41	  saveAccessEvaluationRecords,
42	} from '../constants/evaluation';
43	
44	const formatPct = (v) => `${(v * 100).toFixed(1)}%`;
45	const nowIso = () => new Date().toISOString();
46	
47	const TABS = ['live', 'sim', 'records', 'matrix'];
48	const ORIENTATIONS = ['Front', 'Left Angle', 'Right Angle'];
49	const SIM_ENROL_SOURCES = ['Simulated Pi Camera', 'Simulated Laptop Webcam', 'Temporary Upload'];
50	const READ_SCENARIOS = [
51	  { key: 'active', label: 'Active recognised' },
52	  { key: 'suspended', label: 'Suspended recognised' },
53	  { key: 'unknown', label: 'Unknown person' },
54	  { key: 'noface', label: 'No face' },
55	  { key: 'low-confidence', label: 'Low confidence' },
56	  { key: 'liveness-incomplete', label: 'Liveness incomplete' },
57	  { key: 'pi-offline', label: 'Pi offline -> webcam fallback' },
58	  { key: 'service-offline', label: 'Recognition service offline -> retry/backoff' }
59	];
60	
61	// Map a simulated scenario result onto the shared live-decision card states so
62	// simulated reads look exactly like Gate Scanner / V-Patrol decisions.
63	const simResultToDecision = (result) => {
64	  if (!result) return null;
65	  const base = {
66	    confidence: result.confidence,
67	    latencyMs: result.latencyMs,
68	    actionOverride: result.action,
69	    extraDetails: [['Mode', 'Simulated — no production API called']]
70	  };
71	  if (result.detectionOutcome === DETECTION_OUTCOMES.NO_FACE) {
72	    return { ...base, state: DECISION_STATES.NO_FACE };
73	  }
74	  if (result.access === 'No decision') {
75	    return { ...base, state: DECISION_STATES.NO_FACE, headlineOverride: result.title };
76	  }
77	  if (result.accountState === 'Suspended') {
78	    return { ...base, state: DECISION_STATES.SUSPENDED, identityLabel: result.personLabel };
79	  }
80	  if (result.access === 'Access Granted') {
81	    return { ...base, state: DECISION_STATES.GRANTED, identityLabel: result.personLabel, livenessVerified: true };
82	  }
83	  return {
84	    ...base,
85	    state: DECISION_STATES.UNKNOWN,
86	    headlineOverride: result.personLabel && result.personLabel !== 'Unknown' && result.personLabel !== '-'
87	      ? `${result.personLabel} — Access Denied`
88	      : undefined
89	  };
90	};
91	
92	const FacialEvaluation = () => {
93	  const [searchParams] = useSearchParams();
94	  const paramTab = searchParams.get('tab');
95	  const paramSource = searchParams.get('source');
96	  const paramOrigin = searchParams.get('origin');
97	
98	  const [activeTab, setActiveTab] = useState(TABS.includes(paramTab) ? paramTab : 'sim');
99	  const [records, setRecords] = useState(() => loadRecords());
100	  const [filters, setFilters] = useState({ source: 'All', condition: 'All', date: '', origin: 'All' });
101	  // The matrix defaults to LIVE records: only live records measure the actual
102	  // model. Deep links like ?tab=matrix&source=Live&origin=Gate%20Scanner work.
103	  const [matrixFilters, setMatrixFilters] = useState({
104	    source: ['All', ...SOURCES].includes(paramSource) ? paramSource : 'Live',
105	    condition: 'All',
106	    date: '',
107	    origin: paramOrigin && ORIGINS.includes(paramOrigin) ? paramOrigin : 'All'
108	  });
109	  const [editingId, setEditingId] = useState(null);
110	  const [editDraft, setEditDraft] = useState({});
111	
112	  const [labelMap, setLabelMap] = useState(() => loadLabelMap());
113	  const [enrolledUsers, setEnrolledUsers] = useState([]);
114	  const [mappingDraft, setMappingDraft] = useState({ userId: '', label: 'P01' });
115	  const [mappingError, setMappingError] = useState('');
116	
117	  const [liveInput, setLiveInput] = useState({ actualLabel: '', condition: 'Front', notes: '' });
118	  const [liveResult, setLiveResult] = useState(null);
119	  const [liveDraft, setLiveDraft] = useState(null);
120	  const [liveError, setLiveError] = useState('');
121	  const [cameraSource, setCameraSource] = useState(CAMERA_SOURCES.PI);
122	  const [cameraStatusMsg, setCameraStatusMsg] = useState('Pi camera is preferred for live evaluation.');
123	  const [uploadPreviewUrl, setUploadPreviewUrl] = useState(null);
124	  const [uploadFrame, setUploadFrame] = useState(null);
125	  const videoRef = useRef(null);
126	  const canvasRef = useRef(null);
127	
128	  const [lastResult, setLastResult] = useState(null);
129	  const [simCondition, setSimCondition] = useState('Front');
130	  const [simUsers, setSimUsers] = useState(() => loadSimUsers());
131	  const [simScenario, setSimScenario] = useState('active');
132	  const [simMessage, setSimMessage] = useState('');
133	  const [selectedSimId, setSelectedSimId] = useState('');
134	
135	  // Guided create / re-enrol wizard.
136	  // { mode: 'create'|'reenrol', targetId, step: 1-4, participantLabel, role, enrolmentSource, captured: [] }
137	  const [wizard, setWizard] = useState(null);
138	  const [wizardUploadUrl, setWizardUploadUrl] = useState(null);
139	
140	  const [liveForm, setLiveForm] = useState({ actualLabel: '', predictedLabel: '', confidence: '', condition: 'Front', latencyMs: '', origin: 'Manual', notes: '' });
141	
142	  const token = localStorage.getItem('accessToken');
143	  const [clearDialogOpen, setClearDialogOpen] = useState(false);
144	  const [clearAccessToo, setClearAccessToo] = useState(false);
145	  const { participants: evaluationParticipants, labels: participantLabels, namesByLabel, reload: reloadParticipants } = useEvaluationParticipants();
146	
147	  // Explicit FM-controlled backfill only — never triggered on page load.
148	  const [syncConfirmOpen, setSyncConfirmOpen] = useState(false);
149	  const [syncing, setSyncing] = useState(false);
150	  const [syncMessage, setSyncMessage] = useState('');
151	  const [syncError, setSyncError] = useState('');
152	
153	  const runParticipantSync = async () => {
154	    if (syncing) return;
155	    setSyncing(true);
156	    setSyncMessage('');
157	    setSyncError('');
158	    try {
159	      const response = await axios.post(`${API_BASE_URL}/api/facial-recognition/evaluation-participants/sync`, {}, { headers: { Authorization: `Bearer ${token}` } });
160	      const created = Number(response.data?.synced) || 0;
161	      setSyncMessage(`Participant sync completed. ${created} new mapping(s) created.`);
162	      setSyncConfirmOpen(false);
163	      await reloadParticipants();
164	    } catch {
165	      setSyncError('Participant sync failed. Existing labels were not changed; retry when the server is available.');
166	      setSyncConfirmOpen(false);
167	    } finally {
168	      setSyncing(false);
169	    }
170	  };
171	
172	  const persist = (next) => {
173	    const clean = next.filter(Boolean);
174	    setRecords(clean);
175	    saveRecords(clean);
176	    notifyEvaluationRecordsUpdated();
177	  };
178	  const persistMap = (next) => { setLabelMap(next); saveLabelMap(next); };
179	  const persistSimUsers = (next) => { setSimUsers(next); saveSimUsers(next); };
180	
181	  useEffect(() => () => {
182	    if (uploadPreviewUrl) URL.revokeObjectURL(uploadPreviewUrl);
183	    stopWebcam();
184	  }, [uploadPreviewUrl]);
185	
186	  // Temporary wizard upload preview: object URL only, revoked on
187	  // replacement/unmount — image data is never stored or sent anywhere.
188	  useEffect(() => () => {
189	    if (wizardUploadUrl) URL.revokeObjectURL(wizardUploadUrl);
190	  }, [wizardUploadUrl]);
191	
192	  const loadEnrolledUsers = async () => {
193	    setMappingError('');
194	    try {
195	      const res = await axios.get(`${API_BASE_URL}/user`, { headers: { Authorization: `Bearer ${token}` } });
196	      setEnrolledUsers((Array.isArray(res.data) ? res.data : []).filter((u) => u.isEnrolled));
197	    } catch {
198	      setMappingError('Could not load enrolled users. Check FM access and server availability.');
199	    }
200	  };
201	
202	  const saveMapping = () => {
203	    try {
204	      const next = assignLabel(labelMap, mappingDraft.userId, mappingDraft.label);
205	      persistMap(next);
206	      setMappingError('');
207	    } catch (err) {
208	      setMappingError(err.message);
209	    }
210	  };
211	
212	  const initLiveCamera = async () => {
213	    setLiveError('');
214	    const piReachable = await isPiCameraReachable();
215	    if (piReachable) {
216	      stopWebcam();
217	      setCameraSource(CAMERA_SOURCES.PI);
218	      setCameraStatusMsg(CAMERA_STATUS_MESSAGES.PI_CONNECTED);
219	    } else {
220	      setCameraSource(CAMERA_SOURCES.WEBCAM);
221	      setCameraStatusMsg(CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
222	      await startWebcam();
223	    }
224	  };
225	
226	  const startWebcam = async () => {
227	    if (!navigator.mediaDevices?.getUserMedia) {
228	      setLiveError('No webcam is available. Use temporary upload instead.');
229	      return;
230	    }
231	    const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
232	    if (videoRef.current) videoRef.current.srcObject = stream;
233	  };
234	
235	  const stopWebcam = () => {
236	    if (videoRef.current?.srcObject) {
237	      videoRef.current.srcObject.getTracks().forEach((track) => track.stop());
238	      videoRef.current.srcObject = null;
239	    }
240	  };
241	
242	  const frameFromCamera = async () => {
243	    const canvas = canvasRef.current;
244	    if (!canvas) return null;
245	    const ctx = canvas.getContext('2d');
246	    if (cameraSource === CAMERA_SOURCES.PI) {
247	      const bitmap = await fetchPiSnapshotBitmap();
248	      const scale = Math.min(1, 640 / bitmap.width);
249	      canvas.width = Math.round(bitmap.width * scale);
250	      canvas.height = Math.round(bitmap.height * scale);
251	      ctx.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
252	      bitmap.close?.();
253	      return canvas.toDataURL('image/jpeg', 0.4);
254	    }
255	    const video = videoRef.current;
256	    if (!video || !video.videoWidth) return null;
257	    canvas.width = video.videoWidth;
258	    canvas.height = video.videoHeight;
259	    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
260	    return canvas.toDataURL('image/jpeg', 0.4);
261	  };
262	
263	  const handleUpload = (file) => {
264	    if (!file) return;
265	    if (uploadPreviewUrl) URL.revokeObjectURL(uploadPreviewUrl);
266	    const url = URL.createObjectURL(file);
267	    setUploadPreviewUrl(url);
268	    const reader = new FileReader();
269	    reader.onload = (event) => setUploadFrame(event.target.result);
270	    reader.readAsDataURL(file);
271	  };
272	
273	  const runLiveEvaluate = async (mode = 'camera') => {
274	    setLiveError('');
275	    setLiveResult(null);
276	    setLiveDraft(null);
277	    try {
278	      const frame = mode === 'upload' ? uploadFrame : await frameFromCamera();
279	      if (!frame) {
280	        setLiveError('No temporary frame is available. Capture from camera or choose an upload.');
281	        return;
282	      }
283	      const started = Date.now();
284	      const res = await axios.post(`${API_BASE_URL}/api/facial-recognition/evaluate`, { image: frame }, { headers: { Authorization: `Bearer ${token}` } });
285	      const result = {
286	        matchedUserId: res.data.matchedUserId,
287	        outcome: res.data.outcome,
288	        // The database-backed label is the ONLY prediction source: a
289	        // recognised-but-unmapped user must never degrade to Unknown or be
290	        // blocked by the legacy browser-local label map.
291	        predictedEvaluationLabel: res.data.predictedEvaluationLabel,
292	        confidence: res.data.confidence,
293	        box: res.data.box,
294	        liveness: res.data.liveness,
295	        timings: { ...(res.data.timings || {}), totalRequestMs: res.data.timings?.totalRequestMs ?? Date.now() - started },
296	        user: res.data.outcome === 'MATCHED' ? { id: res.data.matchedUserId, confidence: res.data.confidence } : res.data.outcome === 'UNKNOWN' ? { id: null, confidence: res.data.confidence } : null,
297	        detectionOutcome: res.data.outcome === 'NO_FACE' ? DETECTION_OUTCOMES.NO_FACE : null
298	      };
299	      setLiveResult(result);
300	      setLiveDraft(buildEvaluationDraftFromRecognition({ result, labelMap, origin: 'Live Model Evaluation' }));
301	    } catch (err) {
302	      setLiveError(err.response?.data?.error || 'Model evaluation failed. Camera source is unchanged; retry when the service is ready.');
303	    }
304	  };
305	
306	  const saveLiveDraft = () => {
307	    try {
308	      const rec = saveEvaluationRecordFromDraft(liveDraft, { actualLabel: liveInput.actualLabel, condition: liveInput.condition, notes: liveInput.notes });
309	      persist([rec, ...records]);
310	      setLiveInput({ ...liveInput, notes: '' });
311	      setLiveError('Live evaluation result recorded');
312	    } catch (err) {
313	      setLiveError(err.message);
314	    }
315	  };
316	
317	  const runScenario = (scenario) => setLastResult({ title: scenario.title, ...scenario.run() });
318	
319	  // A simulated evaluation record is only created after this explicit
320	  // confirmation — never automatically from running a scenario.
321	  const logLastResult = () => {
322	    if (!lastResult?.recordable) return;
323	    const rec = createRecord({
324	      actualLabel: lastResult.actualLabel,
325	      predictedLabel: lastResult.predictedLabel,
326	      detectionOutcome: lastResult.detectionOutcome,
327	      confidence: lastResult.confidence,
328	      condition: simCondition,
