1	export const EVAL_STORAGE_KEY = 'flowguard_facial_evaluation_records';
2	export const EVAL_RECORDS_UPDATED_EVENT = 'flowguard:evaluation-records-updated';
3	export const EVAL_LABEL_MAP_KEY = 'flowguard_facial_evaluation_label_map';
4	export const SIM_USERS_KEY = 'flowguard_facial_simulation_users';
5	export const ACCESS_EVAL_STORAGE_KEY = 'flowguard_access_evaluation_records';
6	
7	// Legacy simulated CRUD fixtures only; production classes come from PostgreSQL.
8	export const ENROLLED_LABELS = ['P01', 'P02', 'P03', 'P04', 'P05'];
9	export const UNKNOWN_LABEL = 'Unknown';
10	export const IDENTITY_LABELS = [...ENROLLED_LABELS, UNKNOWN_LABEL];
11	export const NO_FACE = 'No Face';
12	export const DETECTION_OUTCOMES = { NO_FACE: 'NO_FACE' };
13	
14	export const CONDITIONS = ['Front', 'Left Angle', 'Right Angle', 'Normal Lighting', 'Low Lighting', 'Glasses', 'Other'];
15	export const SOURCES = ['Live', 'Simulated'];
16	export const ORIGINS = ['Manual', 'Gate Scanner', 'V-Patrol', 'Live Model Evaluation', 'Image-Based Evaluation', 'Simulated CRUD'];
17	export const LEGACY_CONDITION_MAP = {
18	  front: 'Front',
19	  left: 'Left Angle',
20	  right: 'Right Angle',
21	  'normal-light': 'Normal Lighting',
22	  'low-light': 'Low Lighting'
23	};
24	
25	const defaultStorage = () => (typeof window !== 'undefined' ? window.localStorage : null);
26	const safeJson = (raw, fallback) => {
27	  try {
28	    const parsed = raw ? JSON.parse(raw) : fallback;
29	    return parsed ?? fallback;
30	  } catch {
31	    return fallback;
32	  }
33	};
34	
35	export function normalizeCondition(condition = 'Front') {
36	  return LEGACY_CONDITION_MAP[condition] || condition || 'Front';
37	}
38	
39	export const isEvaluationLabel = (label) => /^P\d+$/.test(String(label || ''));
40	export const evaluationLabelNumber = (label) => { const match = /^P(\d+)$/.exec(String(label || '')); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER; };
41	export const sortEvaluationLabels = (labels = []) => [...new Set(labels.filter(isEvaluationLabel))].sort((a, b) => evaluationLabelNumber(a) - evaluationLabelNumber(b));
42	export function normalizeLabel(label) { if (label === NO_FACE) return NO_FACE; return label === UNKNOWN_LABEL || isEvaluationLabel(label) ? label : UNKNOWN_LABEL; }
43	export function matrixLabelsForRecords(records = [], participantLabels = []) { const historical = records.flatMap((r) => [r.actualLabel, r.predictedLabel]); return [...sortEvaluationLabels([...participantLabels, ...historical]), UNKNOWN_LABEL]; }
44	
45	export function loadRecords(storage = defaultStorage()) {
46	  if (!storage) return [];
47	  const parsed = safeJson(storage.getItem(EVAL_STORAGE_KEY), []);
48	  return Array.isArray(parsed) ? parsed.map(sanitizeRecord).filter(Boolean) : [];
49	}
50	
51	export function saveRecords(records, storage = defaultStorage()) {
52	  if (!storage) return;
53	  storage.setItem(EVAL_STORAGE_KEY, JSON.stringify(records.map(sanitizeRecord).filter(Boolean)));
54	}
55	
56	export function loadLabelMap(storage = defaultStorage()) {
57	  if (!storage) return {};
58	  const parsed = safeJson(storage.getItem(EVAL_LABEL_MAP_KEY), {});
59	  return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
60	}
61	
62	export function saveLabelMap(map, storage = defaultStorage()) {
63	  if (!storage) return;
64	  const clean = {};
65	  Object.entries(map || {}).forEach(([userId, label]) => {
66	    if (ENROLLED_LABELS.includes(label)) clean[String(userId)] = label;
67	  });
68	  storage.setItem(EVAL_LABEL_MAP_KEY, JSON.stringify(clean));
69	}
70	
71	export function labelForUserId(userId, map = loadLabelMap()) {
72	  if (userId == null) return null;
73	  return map[String(userId)] || null;
74	}
75	
76	export function assignLabel(map, userId, label) {
77	  if (!userId || !ENROLLED_LABELS.includes(label)) throw new Error('Choose an enrolled user and a P01-P05 label.');
78	  const next = { ...(map || {}) };
79	  const duplicate = Object.entries(next).find(([existingUserId, existingLabel]) => existingUserId !== String(userId) && existingLabel === label);
80	  if (duplicate) throw new Error(`${label} is already assigned. Remove it before reusing the label.`);
81	  next[String(userId)] = label;
82	  return next;
83	}
84	
85	export function removeMappedUser(map, userId) {
86	  const next = { ...(map || {}) };
87	  delete next[String(userId)];
88	  return next;
89	}
90	
91	let idSeq = 0;
92	export function createRecord({
93	  actualLabel,
94	  predictedLabel,
95	  confidence = null,
96	  condition = 'Front',
97	  latencyMs = null,
98	  source = 'Simulated',
99	  origin = source === 'Live' ? 'Manual' : 'Simulated CRUD',
100	  notes = '',
101	  detectionOutcome = null,
102	  timestamp = new Date().toISOString()
103	}) {
104	  idSeq += 1;
105	  const isNoFace = detectionOutcome === DETECTION_OUTCOMES.NO_FACE || actualLabel === NO_FACE || predictedLabel === NO_FACE;
106	  return sanitizeRecord({
107	    id: `EV-${Date.now().toString(36)}-${idSeq}`,
108	    actualLabel: isNoFace ? null : normalizeLabel(actualLabel),
109	    predictedLabel: isNoFace ? null : normalizeLabel(predictedLabel),
110	    confidence: confidence == null || confidence === '' ? null : Number(confidence),
111	    condition: normalizeCondition(condition),
112	    latencyMs: latencyMs == null || latencyMs === '' ? null : Math.round(Number(latencyMs)),
113	    source: SOURCES.includes(source) ? source : 'Simulated',
114	    origin: origin || 'Manual',
115	    notes: String(notes || '').slice(0, 500),
116	    detectionOutcome: isNoFace ? DETECTION_OUTCOMES.NO_FACE : null,
117	    timestamp
118	  });
119	}
120	
121	export function sanitizeRecord(record) {
122	  if (!record || typeof record !== 'object') return null;
123	  const allowed = {
124	    id: record.id || `EV-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`,
125	    actualLabel: record.detectionOutcome === DETECTION_OUTCOMES.NO_FACE ? null : normalizeLabel(record.actualLabel),
126	    predictedLabel: record.detectionOutcome === DETECTION_OUTCOMES.NO_FACE ? null : normalizeLabel(record.predictedLabel),
127	    confidence: record.confidence == null || record.confidence === '' ? null : Number(record.confidence),
128	    condition: normalizeCondition(record.condition),
129	    latencyMs: record.latencyMs == null || record.latencyMs === '' ? null : Math.round(Number(record.latencyMs)),
130	    source: SOURCES.includes(record.source) ? record.source : 'Simulated',
131	    origin: record.origin || (record.source === 'Live' ? 'Manual' : 'Simulated CRUD'),
132	    notes: String(record.notes || '').slice(0, 500),
133	    detectionOutcome: record.detectionOutcome === DETECTION_OUTCOMES.NO_FACE ? DETECTION_OUTCOMES.NO_FACE : null,
134	    timestamp: record.timestamp || new Date().toISOString()
135	  };
136	  if (allowed.detectionOutcome !== DETECTION_OUTCOMES.NO_FACE && (!allowed.actualLabel || !allowed.predictedLabel)) return null;
137	  return allowed;
138	}
139	
140	export function loadSimUsers(storage = defaultStorage()) {
141	  if (!storage) return [];
142	  const parsed = safeJson(storage.getItem(SIM_USERS_KEY), []);
143	  return Array.isArray(parsed) ? parsed : [];
144	}
145	
146	export function saveSimUsers(users, storage = defaultStorage()) {
147	  if (!storage) return;
148	  const clean = (users || []).map((user) => ({
149	    id: user.id,
150	    participantLabel: user.participantLabel,
151	    role: user.role,
152	    status: user.status,
153	    enrolled: Boolean(user.enrolled),
154	    enrolmentSource: user.enrolmentSource,
155	    enrolledAngles: Array.isArray(user.enrolledAngles) ? user.enrolledAngles : [],
156	    audit: Array.isArray(user.audit) ? user.audit.slice(-20) : [],
157	    createdAt: user.createdAt,
158	    updatedAt: user.updatedAt
159	  }));
160	  storage.setItem(SIM_USERS_KEY, JSON.stringify(clean));
161	}
162	
163	// Tolerant key for matching origins/sources: ignores case, spacing and
164	// punctuation so "gate scanner" / "Gate-Scanner" both match "Gate Scanner".
165	export function normalizeOriginKey(value) {
166	  return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
167	}
168	
169	// Notify any embedded live-matrix panels that the stored records changed —
170	// pure UI refresh signal; never triggers recognition or production writes.
171	export function notifyEvaluationRecordsUpdated(detail = {}) {
172	  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
173	    window.dispatchEvent(new CustomEvent(EVAL_RECORDS_UPDATED_EVENT, { detail }));
174	  }
175	}
176	
177	export function filterRecords(records, { source = 'All', condition = 'All', date = '', origin = 'All' } = {}) {
178	  return records.filter((r) => {
179	    if (source !== 'All' && normalizeOriginKey(r.source) !== normalizeOriginKey(source)) return false;
180	    if (condition !== 'All' && normalizeCondition(r.condition) !== normalizeCondition(condition)) return false;
181	    if (origin !== 'All' && normalizeOriginKey(r.origin) !== normalizeOriginKey(origin)) return false;
182	    if (date && !(r.timestamp || '').startsWith(date)) return false;
183	    return true;
184	  });
185	}
186	
187	const safeDiv = (num, den) => (den > 0 ? num / den : 0);
188	
189	export function computeConfusionMatrix(records, participantLabels = []) {
190	  const labels = matrixLabelsForRecords(records, participantLabels);
191	  const idx = Object.fromEntries(labels.map((l, i) => [l, i]));
192	  const matrix = labels.map(() => labels.map(() => 0));
193	  let noFaceCount = 0;
194	  const identityRecords = [];
195	
196	  for (const r of records) {
197	    if (r.detectionOutcome === DETECTION_OUTCOMES.NO_FACE || r.actualLabel === NO_FACE || r.predictedLabel === NO_FACE) {
198	      noFaceCount += 1;
199	      continue;
200	    }
201	    const actual = normalizeLabel(r.actualLabel);
202	    const predicted = normalizeLabel(r.predictedLabel);
203	    if (idx[actual] == null || idx[predicted] == null) continue;
204	    matrix[idx[actual]][idx[predicted]] += 1;
205	    identityRecords.push({ ...r, actualLabel: actual, predictedLabel: predicted });
206	  }
207	
208	  const sampleCount = identityRecords.length;
209	  let correct = 0;
210	  for (let i = 0; i < labels.length; i++) correct += matrix[i][i];
211	  const accuracy = safeDiv(correct, sampleCount);
212	
213	  const perClass = labels.map((label, i) => {
214	    const tp = matrix[i][i];
215	    const actualTotal = matrix[i].reduce((a, b) => a + b, 0);
216	    const predictedTotal = matrix.reduce((sum, row) => sum + row[i], 0);
217	    const precision = safeDiv(tp, predictedTotal);
218	    const recall = safeDiv(tp, actualTotal);
219	    const f1 = precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : 0;
220	    return { label, tp, actualTotal, predictedTotal, precision, recall, f1 };
221	  });
222	  const present = perClass.filter((c) => c.actualTotal > 0 || c.predictedTotal > 0);
223	  const macroPrecision = safeDiv(present.reduce((s, c) => s + c.precision, 0), present.length);
224	  const macroRecall = safeDiv(present.reduce((s, c) => s + c.recall, 0), present.length);
225	  const macroF1 = safeDiv(present.reduce((s, c) => s + c.f1, 0), present.length);
226	
227	  const unknownRow = matrix[idx.Unknown];
228	  const unknownTotal = unknownRow.reduce((a, b) => a + b, 0);
229	  const enrolledLabels = labels.filter((label) => label !== UNKNOWN_LABEL);
230	  const falseAccepts = enrolledLabels.reduce((sum, label) => sum + unknownRow[idx[label]], 0);
231	  const far = safeDiv(falseAccepts, unknownTotal);
232	
233	  let enrolledTotal = 0;
234	  let falseRejects = 0;
235	  for (const l of enrolledLabels) {
236	    const row = matrix[idx[l]];
237	    enrolledTotal += row.reduce((a, b) => a + b, 0);
238	    falseRejects += row[idx.Unknown];
239	  }
240	  const frr = safeDiv(falseRejects, enrolledTotal);
241	
242	  const withLatency = records.filter((r) => typeof r.latencyMs === 'number' && Number.isFinite(r.latencyMs));
243	  const avgLatencyMs = safeDiv(withLatency.reduce((s, r) => s + r.latencyMs, 0), withLatency.length);
244	
245	  return { labels, matrix, sampleCount, accuracy, macroPrecision, macroRecall, macroF1, far, frr, avgLatencyMs, noFaceCount, noFaceRate: safeDiv(noFaceCount, records.length), perClass };
246	}
247	
248	const csvEscape = (v) => {
249	  const s = String(v ?? '');
250	  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
251	};
252	
253	export function toCsv(records) {
254	  const header = ['id', 'actualLabel', 'predictedLabel', 'confidence', 'condition', 'latencyMs', 'source', 'origin', 'notes', 'detectionOutcome', 'timestamp'];
255	  const rows = records.map((r) => header.map((h) => csvEscape(r[h])).join(','));
256	  return [header.join(','), ...rows].join('\n');
257	}
258	
259	export function buildEvaluationDraftFromRecognition({ result, labelMap = {}, source = 'Live', origin = 'Manual' }) {
260	  const user = result?.user || result?.subject || null;
261	  const timings = result?.timings || {};
262	  const noFace = result?.detectionOutcome === DETECTION_OUTCOMES.NO_FACE || result?.outcome === 'NO_FACE';
263	  if (noFace) {
264	    return {
265	      detectionOutcome: DETECTION_OUTCOMES.NO_FACE,
266	      actualLabel: null,
267	      predictedLabel: null,
268	      confidence: result?.confidence ?? user?.confidence ?? 0,
269	      latencyMs: timings.totalRequestMs ?? timings.nodeToAiMs ?? result?.latencyMs ?? null,
270	      source,
271	      origin,
272	      notes: ''
273	    };
274	  }
275	  const matchedUserId = user?.id ?? result?.matchedUserId ?? null;
276	  const predicted = result?.predictedEvaluationLabel ?? (matchedUserId == null && (result?.outcome === 'UNKNOWN' || Array.isArray(result?.box)) ? UNKNOWN_LABEL : labelForUserId(matchedUserId, labelMap));
277	  return {
278	    actualLabel: UNKNOWN_LABEL,
279	    predictedLabel: predicted === UNKNOWN_LABEL ? UNKNOWN_LABEL : isEvaluationLabel(predicted) ? predicted : null,
280	    needsMapping: Boolean(matchedUserId != null && !isEvaluationLabel(predicted)),
281	    matchedUserId,
282	    confidence: user?.confidence ?? result?.confidence ?? null,
283	    latencyMs: timings.totalRequestMs ?? timings.nodeToAiMs ?? result?.latencyMs ?? null,
284	    source,
285	    origin,
286	    notes: ''
287	  };
288	}
289	
290	export function saveEvaluationRecordFromDraft(draft, { actualLabel, condition, notes = '' }) {
291	  if (draft.needsMapping) throw new Error('Assign evaluation label first.');
292	  if (draft.detectionOutcome === DETECTION_OUTCOMES.NO_FACE) {
293	    return createRecord({ detectionOutcome: DETECTION_OUTCOMES.NO_FACE, condition, confidence: draft.confidence, latencyMs: draft.latencyMs, source: draft.source, origin: draft.origin, notes });
294	  }
295	  if (actualLabel !== UNKNOWN_LABEL && !isEvaluationLabel(actualLabel)) throw new Error('Choose the actual ground-truth label.');
296	  return createRecord({ actualLabel, predictedLabel: draft.predictedLabel || UNKNOWN_LABEL, confidence: draft.confidence, condition, latencyMs: draft.latencyMs, source: draft.source, origin: draft.origin, notes });
297	}
298	
299	export const ACTUAL_AUTHORIZATION = { AUTHORIZED: 'Actually Authorised', UNAUTHORIZED: 'Actually Unauthorised' };
300	export const ACCESS_DECISIONS = { GRANTED: 'Access Granted', DENIED: 'Access Denied' };
301	
302	export function sanitizeAccessEvaluationRecord(record) {
