1	// FM-only "Evaluation Participants" sync card on the Facial Evaluation page.
2	// Verifies the explicit FM-controlled backfill: confirmation-gated, single
3	// POST to the sync endpoint only, safe success/failure messaging, participant
4	// reload after success, and zero operational or biometric surface area.
5	import React from "react";
6	import { render, screen, fireEvent, cleanup, waitFor, within } from "@testing-library/react";
7	import { MemoryRouter } from "react-router-dom";
8	import { describe, test, expect, vi, beforeEach, afterEach } from "vitest";
9	import "@testing-library/jest-dom";
10	
11	vi.mock("../../src/components/Sidebar", () => ({ default: () => <div data-testid="sidebar" /> }));
12	
13	const mockAxios = vi.hoisted(() => ({
14	  get: vi.fn(), post: vi.fn(), put: vi.fn(), patch: vi.fn(), delete: vi.fn(),
15	}));
16	vi.mock("axios", () => ({ default: mockAxios }));
17	
18	import FacialEvaluation from "../../src/pages/FacialEvaluation";
19	
20	const PARTICIPANTS_URL = "/api/facial-recognition/evaluation-participants";
21	const SYNC_URL = "/api/facial-recognition/evaluation-participants/sync";
22	
23	const participants = [
24	  { userId: 1, evaluationLabel: "P01", name: "System Root Admin", role: "FM", isActive: true, isEnrolled: true },
25	  { userId: 2, evaluationLabel: "P02", name: "Staff Name", role: "Staff", isActive: true, isEnrolled: true },
26	  { userId: 3, evaluationLabel: "P03", name: "Tenant Name", role: "Tenant", isActive: true, isEnrolled: true },
27	];
28	
29	const renderPage = () => render(<MemoryRouter><FacialEvaluation /></MemoryRouter>);
30	
31	const getCard = () => screen.getByTestId("evaluation-participants-card");
32	const openConfirm = () => fireEvent.click(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" }));
