48	
49	describe("Evaluation Participants sync card", () => {
50	  test("renders the active participant count and the FM sync button, without auto-syncing", async () => {
51	    renderPage();
52	    expect(await within(getCard()).findByText("Active participants: 3")).toBeInTheDocument();
53	    expect(within(getCard()).getByText("Assign stable evaluation labels to existing Face ID-enrolled users.")).toBeInTheDocument();
54	    expect(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" })).toBeEnabled();
55	    // Read-only on load: GET only, never the POST sync endpoint.
56	    expect(mockAxios.get).toHaveBeenCalledWith(expect.stringContaining(PARTICIPANTS_URL), expect.anything());
57	    expect(mockAxios.post).not.toHaveBeenCalled();
58	  });
59	
60	  test("legend comes from the participant endpoint, not hardcoded names", async () => {
61	    mockAxios.get.mockResolvedValue({
62	      data: { participants: [{ userId: 9, evaluationLabel: "P07", name: "Endpoint-Sourced Person", role: "Staff", isActive: true, isEnrolled: true }] },
63	    });
64	    renderPage();
65	    const legend = await screen.findByTestId("participant-legend");
66	    expect(within(legend).getByText("P07")).toBeInTheDocument();
67	    expect(within(legend).getByText("Endpoint-Sourced Person")).toBeInTheDocument();
68	    expect(screen.getByText("Active participants: 1")).toBeInTheDocument();
69	  });
70	
71	  test("clicking sync opens a confirmation explaining that existing labels are not changed", async () => {
72	    renderPage();
73	    await within(getCard()).findByText("Active participants: 3");
74	    openConfirm();
75	    const dialog = getDialog();
76	    expect(within(dialog).getByText(/Existing labels will not be changed/)).toBeInTheDocument();
77	    expect(within(dialog).getByText(/only eligible Face ID-enrolled users receive labels/)).toBeInTheDocument();
78	    expect(mockAxios.post).not.toHaveBeenCalled();
79	  });
80	
81	  test("cancelling the confirmation makes no request", async () => {
82	    renderPage();
83	    await within(getCard()).findByText("Active participants: 3");
84	    openConfirm();
85	    fireEvent.click(within(getDialog()).getByRole("button", { name: "Cancel" }));
86	    expect(screen.queryByRole("dialog", { name: "Sync Enrolled Participants" })).toBeNull();
87	    expect(mockAxios.post).not.toHaveBeenCalled();
88	  });
89	
90	  test("confirming calls ONLY the sync endpoint, shows the success count, and reloads participants", async () => {
91	    mockAxios.post.mockResolvedValue({ data: { synced: 2, participants } });
92	    renderPage();
93	    await within(getCard()).findByText("Active participants: 3");
94	    const getCallsBefore = mockAxios.get.mock.calls.length;
95	
96	    openConfirm();
97	    fireEvent.click(within(getDialog()).getByRole("button", { name: "Confirm Sync" }));
98	
99	    expect(await screen.findByText("Participant sync completed. 2 new mapping(s) created.")).toBeInTheDocument();
100	    // Exactly one POST, and only to the sync endpoint.
101	    expect(mockAxios.post).toHaveBeenCalledTimes(1);
102	    expect(mockAxios.post.mock.calls[0][0]).toContain(SYNC_URL);
103	    // The shared participant hook reloads after success.
104	    await waitFor(() => expect(mockAxios.get.mock.calls.length).toBeGreaterThan(getCallsBefore));
105	    // Existing labels stay unchanged in the reloaded legend.
106	    const legend = screen.getByTestId("participant-legend");
107	    for (const label of ["P01", "P02", "P03"]) expect(within(legend).getByText(label)).toBeInTheDocument();
108	  });
109	
110	  test("button is disabled while syncing and duplicate submissions are prevented", async () => {
111	    let resolveSync;
112	    mockAxios.post.mockImplementation(() => new Promise((resolve) => { resolveSync = resolve; }));
113	    renderPage();
114	    await within(getCard()).findByText("Active participants: 3");
115	
116	    openConfirm();
117	    const confirmBtn = within(getDialog()).getByRole("button", { name: "Confirm Sync" });
118	    fireEvent.click(confirmBtn);
119	
120	    // In-flight: modal button disabled + card button disabled; extra clicks do nothing.
121	    expect(screen.getByRole("button", { name: "Syncing…" })).toBeDisabled();
122	    expect(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" })).toBeDisabled();
123	    fireEvent.click(screen.getByRole("button", { name: "Syncing…" }));
124	    fireEvent.click(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" }));
125	    expect(mockAxios.post).toHaveBeenCalledTimes(1);
126	
127	    resolveSync({ data: { synced: 0, participants } });
128	    expect(await screen.findByText("Participant sync completed. 0 new mapping(s) created.")).toBeInTheDocument();
129	    expect(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" })).toBeEnabled();
