138	    fireEvent.click(within(getDialog()).getByRole("button", { name: "Confirm Sync" }));
139	
140	    expect(await screen.findByText(/Participant sync failed\. Existing labels were not changed/)).toBeInTheDocument();
141	    expect(document.body.textContent).not.toMatch(/ECONNREFUSED|stack|127\.0\.0\.1/);
142	    expect(within(getCard()).getByRole("button", { name: "Sync Enrolled Participants" })).toBeEnabled();
143	  });
144	
145	  test("the sync flow never calls Attendance, SecurityLog, access-event, recognise or evaluate APIs", async () => {
146	    mockAxios.post.mockResolvedValue({ data: { synced: 1, participants } });
147	    renderPage();
148	    await within(getCard()).findByText("Active participants: 3");
149	
150	    openConfirm();
151	    fireEvent.click(within(getDialog()).getByRole("button", { name: "Confirm Sync" }));
152	    await screen.findByText("Participant sync completed. 1 new mapping(s) created.");
153	
154	    const allUrls = [...mockAxios.get.mock.calls, ...mockAxios.post.mock.calls].map(([url]) => url);
155	    for (const url of allUrls) {
156	      expect(url).not.toMatch(/attendance|security|access-event|recognise|recognize|\/evaluate\b/i);
157	    }
158	    expect(mockAxios.put).not.toHaveBeenCalled();
159	    expect(mockAxios.patch).not.toHaveBeenCalled();
160	    expect(mockAxios.delete).not.toHaveBeenCalled();
161	  });
162	
163	  test("no biometric or credential data is ever rendered", async () => {
164	    mockAxios.post.mockResolvedValue({ data: { synced: 1, participants } });
165	    renderPage();
166	    await within(getCard()).findByText("Active participants: 3");
167	    openConfirm();
168	    fireEvent.click(within(getDialog()).getByRole("button", { name: "Confirm Sync" }));
169	    await screen.findByText(/Participant sync completed/);
170	    expect(document.body.textContent).not.toMatch(/faceVector|embedding|data:image|base64|password|tokenVersion/i);
171	  });
